refentry.refsect1:
&reftitle.description;
boolsocket_set_option Socketsocket intlevel intoption arraystringintvalue
La funzione socket_set_option imposta l'opzione specificata dal parametro option, al livello di protocollo level specificato, al valore puntato dal parametro value per il socket.

&reftitle.changelog;





    &Version;
    &Description;





    8.5.0

     Ora lancia un'eccezione quando si usa MCAST_LEAVE_GROUP
     o MCAST_LEAVE_SOURCE_GROUP e il
     valore non è un oggetto o un array valido, e lancia un
     ValueError quando si usa un'opzione multicast
     su un socket che non è della famiglia AF_INET o
     AF_INET6.


   &sockets.changelog.socket-param;

  &reftitle.examples;



    Esempio di socket_set_option


<?php
$socket = socket_create(AF_INET, SOCK_STREAM, SOL_TCP);

if (!is_resource($socket)) {
    echo 'Impossibile creare il socket: '. socket_strerror(socket_last_error()) . PHP_EOL;
}

if (!socket_set_option($socket, SOL_SOCKET, SO_REUSEADDR, 1)) {
    echo 'Impossibile impostare l\'opzione sul socket: '. socket_strerror(socket_last_error()) . PHP_EOL;
}

if (!socket_bind($socket, '127.0.0.1', 1223)) {
    echo 'Impossibile associare il socket: '. socket_strerror(socket_last_error()) . PHP_EOL;
}

$rval = socket_get_option($socket, SOL_SOCKET, SO_REUSEADDR);

if ($rval === false) {
    echo 'Impossibile ottenere l\'opzione del socket: '. socket_strerror(socket_last_error()) . PHP_EOL;
} else if ($rval !== 0) {
    echo 'SO_REUSEADDR è impostata sul socket!' . PHP_EOL;
}
?>
